50|        [this, &c, &col_scratch](double) {
51|            const std::size_t col = c++;
52|            std::size_t r = 0;
53|            std::transform(col_scratch.begin(), col_scratch.end(),
54|                           col_scratch.begin(),
55|                [this, col, &r](double) { return at(r++, col); });
56|            return std::accumulate(col_scratch.begin(), col_scratch.end(), 0.0);
57|        });
